def find_path(graph, start, goal):
    def dfs(node):
        if node == goal:
            return [goal]  # Return the goal node as the path
        visited.add(node)  # Mark the node as visited
        path = []
        for neighbor in graph[node]:
            if neighbor not in visited:
                path.extend(dfs(neighbor))
                if path:
                    return [node] + path  # Start the path with the current node
        return None

    visited = set()
    return dfs(start)

