def find_path(graph, start, goal):
    # Initialize the stack for DFS
    frontier = [(start, [start])]
    # Initialize the explored set
recurse_set = set()
    # Keep track of the path
    path = None

    while frontier:
        (vertex, path) = frontier.pop()
        if vertex in recurse_set:
            continue
        else:
            recurse_set.add(vertex)

        if vertex == goal:
            return path

        # Expand the node and add its neighbors to the frontier
        for next_node in graph[vertex]:
            if next_node not in recurse_set:
                frontier.append((next_node, path + [next_node]))

    # If the goal is not reachable
    return None
