def find_path(graph, start, goal):
    # Initialize the visited dictionary to keep track of visited nodes
    visited = {}
    # Initialize the path dictionary with the current node (start) to avoid infinite loops
    path = {start: None}
    # Initialize the stack for DFS
    stack = [start]

    # Perform DFS to explore the graph
    while stack:
        current = stack.pop()
        if current == goal:
            # If the goal is reached, reconstruct the path
            path_found = []
            while current is not None:
                path_found.append(current)
                current = path[current]
            return path_found[::-1]  # Reverse the list to get the correct order

        if current not in visited:
            visited[current] = True
            # Add all unvisited neighbors to the stack
            stack.extend(node for node in graph[current] if node not in visited)

            # Add the current node to the path dictionary
            for node in graph[current]:
                if node not in path:
                    path[node] = current

    # If the goal is unreachable, return None
    return None
