def find_path(graph, start, goal):
    """
    Find a path from start to goal in the given graph.

    :param graph: A dictionary representing the graph, where each key is a node and the value is a list of neighboring nodes.
    :param start: The starting node.
    :param goal: The goal node.
    :return: A list of nodes from start to goal (inclusive), or None if goal is unreachable.
    """
    if start not in graph or goal not in graph:
        return None

    path_memory = {}

    def search(node, previous_node=None):
        if node == goal:
            return [node]
        if node in path_memory:
            return path_memory[node]

        for neighbor in graph[node]:
            if neighbor == previous_node:
                continue
            path = search(neighbor, node)
            if path:
                path_memory[node] = [node] + path
                return path_memory[node]

        path_memory[node] = []
        return None

    return search(start)

